Q: How to get All Section Names from ini file A: <p>This is how to use GetPrivateProfileSectionNames.<br />
<a href="https://learn.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-getprivateprofilesectionnames" rel="nofollow noreferrer">https://learn.microsoft.com/en-us/windows/win32/api/winbase/nf-winbase-getprivateprofilesectionnames</a></p>
<blockquote>
<pre><code>DWORD GetPrivateProfileSectionNames(
  [out] LPTSTR  lpszReturnBuffer,
  [in]  DWORD   nSize,
  [in]  LPCTSTR lpFileName
);
</code></pre>
<h2>Parameters</h2>
<p><code>[out] lpszReturnBuffer</code><br />
A pointer to a buffer that receives the section names associated with the named file. The buffer is filled with one or more <strong>null</strong>-terminated strings; the last string is followed by a second <strong>null</strong> character.</p>
<p><code>[in] nSize</code><br />
The size of the buffer pointed to by the <em>lpszReturnBuffer</em> parameter, in characters.</p>
<p><code>[in] lpFileName</code><br />
The name of the initialization file. If this parameter is <strong>NULL</strong>, the function searches the Win.ini file. If this parameter does not contain a full path to the file, the system searches for the file in the Windows directory.</p>
<p><strong>Return value</strong></p>
<p>The return value specifies the number of characters copied to the specified buffer, not including the terminating <strong>null</strong> character. If the buffer is not large enough to contain all the section names associated with the specified initialization file, the return value is equal to the size specified by <em>nSize</em> minus two.</p>
</blockquote>
<p>MFC:</p>
<pre class="lang-cpp prettyprint-override"><code>CString strBuffer;
DWORD uBufSize = 255; // Start with an initial small buffer size

while (true)
{
    // should check the limit of uBufSize after increasing it

    auto buff = strBuffer.GetBuffer(uBufSize);
    // Fill buffer with null-terminated section names; ends with double null
    auto nCopied  = GetPrivateProfileSectionNames(buff,
        uBufSize,
        filePath);
    strBuffer.ReleaseBuffer();

    // If buffer is too small, double its size and retry
    if (nCopied == uBufSize - 2) // the last string is followed by a second null character
        uBufSize += 255;
    else
        break;
}

// Loop through each section name in the buffer
auto pItem = strBuffer.GetBuffer();
while (*pItem != _T('\0')) {
    CString strSection(pItem); // Get current section name
    TRACE(_T(&quot;%s\n&quot;), strSection.GetString());
    pItem += strSection.GetLength() + 1; // Move to next section name
}
</code></pre>
<p>C#:</p>
<pre class="lang-cs prettyprint-override"><code>[DllImport(&quot;kernel32.dll&quot;, CharSet = CharSet.Unicode)]
private static extern uint GetPrivateProfileSectionNames(
[Out] char[] lpszReturnBuffer,
uint nSize,
string lpFileName);

public static string[] GetSectionNames(string filePath)
{
    var uBufSize = 255; // Start with an initial small buffer size
    char[] buffer;
    uint nCopied;

    while (true)
    {
        // should check the limit of uBufSize after increasing it

        buffer = new char[uBufSize];
        nCopied = GetPrivateProfileSectionNames(buffer, (uint)uBufSize, filePath);

        // If buffer is too small, double its size and retry
        if (nCopied == uBufSize - 2) // the last string is followed by a second null character
            uBufSize += 255;
        else
            break;
    }

    // Convert the buffer into a string
    // The buffer contains section names separated by '\0'
    string allSections = new(buffer, 0, (int)nCopied);

    // Split the string into individual section names using '\0' as the separator
    string[] sections = allSections.Split(new char[] { '\0' }, StringSplitOptions.RemoveEmptyEntries);

    return sections;
}
</code></pre>
